  bottom: auto !important;
  left: var(--r-edge) !important;
  right: auto !important;
}
.msg-me .msg-reaction-badge::before { left: 1px;  right: auto; }
.msg-me .msg-reaction-badge::after  { left: -3px; right: auto; }

/* 图片排版与限制 */
:root {
  --image-msg-max-width: 180px;
  --image-msg-radius: 20px;
  --image-msg-shadow: 0 4px 14px rgba(0, 0, 0, 0.20);
  --c-overlap: -28px;
  --c-x1: 56px;
  --c-xl: 48px;
  --c-x2: 28px;
  --c-x3: 40px;
}
.chat-detail-screen .msg-image-wrapper,
.chat-detail-screen .msg-image-card {
  max-width: var(--image-msg-max-width) !important;
  max-height: 220px !important;
  border-radius: var(--image-msg-radius) !important;
  overflow: hidden !important;
  box-shadow: var(--image-msg-shadow) !important;
}
.chat-detail-screen .msg-image-wrapper img,
.chat-detail-screen .msg-image-card img {
  width: 100% !important;
  height: auto !important;
  max-height: 320px !important;
  object-fit: cover !important;
  border-radius: inherit !important;
  display: block !important;
}
.chat-detail-screen [class*="sticker"],
.chat-detail-screen .msg-sticker,
.chat-detail-screen img[class*="emoji"],
.chat-detail-screen img[class*="sticker"] {
  max-width: 130px !important;
  max-height: 130px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
}
.chat-detail-screen .msg-bubble-wrapper .msg-image-wrapper {
  position: relative !important;
  overflow: visible !important;
  border-radius: 20px !important;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.28) !important;
}
.chat-detail-screen .msg-bubble-wrapper .msg-image-wrapper img,
.chat-detail-screen .msg-bubble-wrapper .msg-image-wrapper video,
.chat-detail-screen .msg-bubble-wrapper .msg-image-wrapper .live-photo-layer {
  border-radius: 20px !important;
}

/* 往上压：只有「前一行也是图片」才压，所以不会压到文字 */
:has(.msg-image-wrapper) + *:has(.msg-image-wrapper) .msg-bubble-wrapper:has(.msg-image-wrapper) {
  margin-top: var(--c-overlap) !important;
}

/* ============ 一、整组都是图片（第一条就是图片） ============ */
/* 第 1 张：后面紧跟着还有图才缩进 */
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper):has(+ * .msg-image-wrapper) { --gx: var(--c-x1); }
/* 第 2 张：贴边 */
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * { --gx: 0px; }
/* 第 3、4 张：五张的排法 */
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * + *,
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * + * + * { --gx: var(--c-xl); }
/* 第 5 张：贴边 */
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * + * + * + * { --gx: 0px; }
/* 三张：第 3 张是最后一条 */
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * + *:has(.msg-bubble-wrapper.is-last) { --gx: var(--c-x3); }
/* 四张：第 3 张后面紧跟着最后一条；第 4 张就是最后一条 */
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * + *:has(+ * .msg-bubble-wrapper.is-last) { --gx: var(--c-x2); }
*:has(.msg-bubble-wrapper.is-first .msg-image-wrapper) + * + * + *:has(.msg-bubble-wrapper.is-last) { --gx: var(--c-x3); }

/* ============ 二、文字开头，后面接图片 ============ */
/* 第 1 张图：后面紧跟着还有图才缩进 */
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + *:has(.msg-image-wrapper):has(+ * .msg-image-wrapper) { --gx: var(--c-x1); }
/* 第 2 张图：贴边 */
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * { --gx: 0px; }
/* 第 3、4 张图：五张的排法 */
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * + *,
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * + * + * { --gx: var(--c-xl); }
/* 第 5 张图：贴边 */
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * + * + * + * { --gx: 0px; }
/* 三张图：第 3 张是最后一条 */
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * + *:has(.msg-bubble-wrapper.is-last) { --gx: var(--c-x3); }
/* 四张图：第 3 张后面紧跟着最后一条；第 4 张就是最后一条 */
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * + *:has(+ * .msg-bubble-wrapper.is-last) { --gx: var(--c-x2); }
*:has(.msg-bubble-wrapper.is-first):not(:has(.msg-image-wrapper)) + * + * + * + *:has(.msg-bubble-wrapper.is-last) { --gx: var(--c-x3); }

/* 应用：对方往右缩进，我方往左缩进 */
.chat-detail-screen .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-them .msg-image-wrapper {
  transform: translateX(var(--gx, 0px)) !important;
}
.chat-detail-screen .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-me .msg-image-wrapper {
  transform: translateX(calc(var(--gx, 0px) * -1)) !important;
}

