.chat-detail-screen > .chat-header-custom::before {
  background: linear-gradient(to bottom,
    rgba(255, 255, 255, 0.86) 0%, rgba(255, 255, 255, 0.86) 28%,
    rgba(255, 255, 255, 0.82) 36%, rgba(255, 255, 255, 0.75) 44%,
