  background-size: cover !important;       /* 铺满，不拉伸 */
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* 文字图：平时只显示背景图，点击才显示里面的内容 */
.msg-sim-card {
  cursor: pointer !important;                 /* 让苹果的浏览器把轻点当成「悬停」 */
  -webkit-tap-highlight-color: transparent;
  transition: box-shadow 0.25s ease;
}

/* 卡片里所有内容默认隐藏（只是变透明，卡片大小不变） */
.msg-sim-card > * {
  opacity: 0 !important;
